"use client";
import * as React from "react";
import { cn } from "../lib/cn";
import { Icon } from "../icons/icon";
import { Popover, PopoverContent, PopoverTrigger } from "./popover";
import { Calendar, type CalendarProps } from "./calendar";
import { useControllableState } from "../lib/hooks";
import { useFieldProps } from "./field";
import {
  DEFAULT_LOCALE,
  type DateRange,
  formatDate,
  formatDateRange,
} from "../lib/date";

type CalendarOptions = Pick<
  CalendarProps & { mode?: never },
  "min" | "max" | "disabled" | "weekStartsOn" | "showWeekNumbers" | "markers" | "locale"
>;

export interface DatePickerProps extends CalendarOptions {
  value?: Date | null;
  defaultValue?: Date | null;
  onValueChange?: (date: Date | null) => void;
  placeholder?: string;
  /** Opmaak van de getoonde datum. */
  format?: Intl.DateTimeFormatOptions;
  size?: "sm" | "md" | "lg";
  invalid?: boolean;
  disabledInput?: boolean;
  /** Toont een wisknop wanneer er een datum gekozen is. */
  clearable?: boolean;
  /** Knop "Vandaag" onderaan de kalender. */
  showToday?: boolean;
  id?: string;
  className?: string;
  "aria-describedby"?: string;
}

/** DatePicker — invoerveld met kalender in een popover. */
export const DatePicker = React.forwardRef<HTMLButtonElement, DatePickerProps>(function DatePicker(
  {
    value,
    defaultValue = null,
    onValueChange,
    placeholder = "Kies een datum",
    format = { day: "2-digit", month: "long", year: "numeric" },
    size = "md",
    invalid,
    disabledInput,
    clearable,
    showToday = true,
    locale = DEFAULT_LOCALE,
    className,
    id,
    ...calendarOptions
  },
  ref
) {
  const [open, setOpen] = React.useState(false);
  const [date, setDate] = useControllableState<Date | null>({
    value,
    defaultValue,
    onChange: onValueChange,
  });

  const field = useFieldProps({ id, disabled: disabledInput, invalid }) as {
    id?: string;
    disabled?: boolean;
    invalid?: boolean;
    "aria-describedby"?: string;
  };

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <button
          ref={ref}
          type="button"
          id={field.id}
          disabled={field.disabled}
          aria-invalid={field.invalid || undefined}
          aria-describedby={field["aria-describedby"]}
          data-state={open ? "open" : "closed"}
          className={cn(
            "pxui-datefield",
            `pxui-datefield-${size}`,
            field.invalid && "pxui-datefield-invalid",
            className
          )}
        >
          <Icon name="calendar" size={16} className="pxui-datefield-icon" />
          <span className={cn("pxui-datefield-value", !date && "pxui-datefield-placeholder")}>
            {date ? formatDate(date, format, locale) : placeholder}
          </span>
          {clearable && date && !field.disabled && (
            <span
              role="button"
              tabIndex={-1}
              aria-label="Datum wissen"
              className="pxui-datefield-clear"
              onClick={(event) => {
                event.stopPropagation();
                setDate(null);
              }}
            >
              <Icon name="x" size={14} />
            </span>
          )}
        </button>
      </PopoverTrigger>

      <PopoverContent align="start" flush className="pxui-datefield-popover">
        <Calendar
          mode="single"
          selected={date}
          defaultMonth={date ?? undefined}
          locale={locale}
          onSelect={(next) => {
            setDate(next);
            if (next) setOpen(false);
          }}
          footer={
            showToday ? (
              <button
                type="button"
                className="pxui-datefield-today"
                onClick={() => {
                  setDate(new Date());
                  setOpen(false);
                }}
              >
                Vandaag
              </button>
            ) : undefined
          }
          {...calendarOptions}
        />
      </PopoverContent>
    </Popover>
  );
});

export interface DateRangePickerProps extends CalendarOptions {
  value?: DateRange | null;
  defaultValue?: DateRange | null;
  onValueChange?: (range: DateRange) => void;
  placeholder?: string;
  size?: "sm" | "md" | "lg";
  invalid?: boolean;
  disabledInput?: boolean;
  clearable?: boolean;
  /** Aantal maanden naast elkaar in de popover. */
  numberOfMonths?: number;
  /** Snelkeuzes links van de kalender, bv. "Deze week". */
  presets?: Array<{ label: string; range: DateRange }>;
  id?: string;
  className?: string;
}

/** DateRangePicker — periode kiezen (van – tot) in één popover. */
export const DateRangePicker = React.forwardRef<HTMLButtonElement, DateRangePickerProps>(
  function DateRangePicker(
    {
      value,
      defaultValue = null,
      onValueChange,
      placeholder = "Kies een periode",
      size = "md",
      invalid,
      disabledInput,
      clearable,
      numberOfMonths = 2,
      presets,
      locale = DEFAULT_LOCALE,
      className,
      id,
      ...calendarOptions
    },
    ref
  ) {
    const [open, setOpen] = React.useState(false);
    const [range, setRange] = useControllableState<DateRange | null>({
      value,
      defaultValue,
      onChange: (next) => onValueChange?.(next ?? {}),
    });

    const label = range?.from ? formatDateRange(range, locale) : placeholder;

    return (
      <Popover open={open} onOpenChange={setOpen}>
        <PopoverTrigger asChild>
          <button
            ref={ref}
            type="button"
            id={id}
            disabled={disabledInput}
            aria-invalid={invalid || undefined}
            data-state={open ? "open" : "closed"}
            className={cn(
              "pxui-datefield",
              `pxui-datefield-${size}`,
              invalid && "pxui-datefield-invalid",
              className
            )}
          >
            <Icon name="calendar" size={16} className="pxui-datefield-icon" />
            <span className={cn("pxui-datefield-value", !range?.from && "pxui-datefield-placeholder")}>
              {label}
            </span>
            {clearable && range?.from && !disabledInput && (
              <span
                role="button"
                tabIndex={-1}
                aria-label="Periode wissen"
                className="pxui-datefield-clear"
                onClick={(event) => {
                  event.stopPropagation();
                  setRange({});
                }}
              >
                <Icon name="x" size={14} />
              </span>
            )}
          </button>
        </PopoverTrigger>

        <PopoverContent align="start" flush className="pxui-datefield-popover">
          <div className="pxui-daterange">
            {presets && presets.length > 0 && (
              <div className="pxui-daterange-presets">
                {presets.map((preset) => (
                  <button
                    key={preset.label}
                    type="button"
                    className="pxui-daterange-preset"
                    onClick={() => {
                      setRange(preset.range);
                      setOpen(false);
                    }}
                  >
                    {preset.label}
                  </button>
                ))}
              </div>
            )}
            <Calendar
              mode="range"
              selected={range}
              numberOfMonths={numberOfMonths}
              defaultMonth={range?.from ?? undefined}
              locale={locale}
              onSelect={(next) => {
                setRange(next);
                if (next.from && next.to) setOpen(false);
              }}
              {...calendarOptions}
            />
          </div>
        </PopoverContent>
      </Popover>
    );
  }
);

/* ============================ DatePicker ============================ */
.pxui-datefield {
  display: flex; align-items: center; gap: 9px;
  width: 100%; height: calc(42px * var(--density)); padding: 0 11px 0 13px;
  background: var(--surface); color: var(--text);
  border: 1px solid var(--border-strong); border-radius: var(--r-sm);
  font: inherit; font-size: var(--fs-base); text-align: left; cursor: pointer;
  transition: border-color var(--dur-fast), box-shadow var(--dur-fast);
}
.pxui-datefield:hover:not(:disabled) { border-color: var(--text-3); }
.pxui-datefield:focus-visible { outline: none; border-color: var(--accent); box-shadow: var(--ring); }
.pxui-datefield[data-state="open"] { border-color: var(--accent); box-shadow: var(--ring); }
.pxui-datefield:disabled { background: var(--surface-3); color: var(--text-2); cursor: not-allowed; }

.pxui-datefield-sm { height: calc(34px * var(--density)); padding: 0 9px 0 10px; font-size: 13px; border-radius: var(--r-xs); }
.pxui-datefield-lg { height: calc(48px * var(--density)); padding: 0 13px 0 15px; font-size: var(--fs-md); border-radius: var(--r-md); }

.pxui-datefield-icon { flex: none; color: var(--text-3); }
.pxui-datefield-value {
  flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.pxui-datefield-placeholder { color: var(--text-3); }
.pxui-datefield-invalid { border-color: var(--red); }
.pxui-datefield-invalid:focus-visible { border-color: var(--red); box-shadow: var(--ring-red); }

.pxui-datefield-clear {
  display: inline-grid; place-items: center; flex: none;
  width: 20px; height: 20px; border-radius: var(--r-full); color: var(--text-3);
  transition: background var(--dur-fast), color var(--dur-fast);
}
.pxui-datefield-clear:hover { background: var(--surface-3); color: var(--text); }

.pxui-datefield-popover { padding: 12px; }

.pxui-datefield-today {
  border: 1px solid var(--border-strong); background: var(--surface);
  border-radius: var(--r-xs); padding: 5px 11px;
  font: inherit; font-size: 12.5px; font-weight: 600; color: var(--text);
  cursor: pointer; transition: background var(--dur-fast);
}
.pxui-datefield-today:hover { background: var(--surface-hover); }

/* ---------- DateRangePicker ---------- */
.pxui-daterange { display: flex; gap: 14px; }
.pxui-daterange-presets {
  display: flex; flex-direction: column; gap: 3px;
  padding-right: 14px; border-right: 1px solid var(--border); min-width: 132px;
}
.pxui-daterange-preset {
  border: none; background: transparent; border-radius: var(--r-xs);
  padding: 7px 10px; text-align: left;
  font: inherit; font-size: 13px; font-weight: 550; color: var(--text-2);
  cursor: pointer; transition: background var(--dur-fast), color var(--dur-fast);
}
.pxui-daterange-preset:hover { background: var(--surface-3); color: var(--text); }
.pxui-daterange-preset:focus-visible { outline: none; box-shadow: var(--ring); }

@media (max-width: 640px) {
  .pxui-daterange { flex-direction: column; }
  .pxui-daterange-presets {
    flex-direction: row; flex-wrap: wrap; min-width: 0;
    padding-right: 0; padding-bottom: 10px;
    border-right: none; border-bottom: 1px solid var(--border);
  }
}
